// Shared request-input validators for the account-data API routes. Activity
// ids are generated by the content pipeline as lowercase slug-like strings
// (e.g. "switzerland--bivouac-..."), so this both rejects obvious garbage
// early and caps size against a client sending something huge.
const ACTIVITY_ID_RE = /^[a-z0-9-]{1,200}$/;
const MAX_REVIEW_TEXT_LENGTH = 2000;
const MAX_SYNC_LIST_LENGTH = 500;

export function isValidActivityId(value: unknown): value is string {
  return typeof value === "string" && ACTIVITY_ID_RE.test(value);
}

export function isValidRating(value: unknown): value is number {
  return typeof value === "number" && Number.isInteger(value) && value >= 1 && value <= 5;
}

export function isValidReviewText(value: unknown): value is string {
  return typeof value === "string" && value.length <= MAX_REVIEW_TEXT_LENGTH;
}

export function isValidSyncFavorites(value: unknown): value is string[] {
  return (
    Array.isArray(value) &&
    value.length <= MAX_SYNC_LIST_LENGTH &&
    value.every((id) => isValidActivityId(id))
  );
}

export function isValidSyncReviews(
  value: unknown
): value is Record<string, { rating: number; text: string; updatedAt: string }> {
  if (typeof value !== "object" || value === null || Array.isArray(value)) return false;
  const entries = Object.entries(value as Record<string, unknown>);
  if (entries.length > MAX_SYNC_LIST_LENGTH) return false;
  return entries.every(([activityId, review]) => {
    if (!isValidActivityId(activityId)) return false;
    if (typeof review !== "object" || review === null) return false;
    const r = review as Record<string, unknown>;
    return (
      isValidRating(r.rating) &&
      isValidReviewText(r.text) &&
      typeof r.updatedAt === "string" &&
      r.updatedAt.length <= 64
    );
  });
}
